"""Run Django's ``tests/runtests.py`` in a worktree and classify the outcome.

Outcome classes: PASS / FAIL / ERROR / SKIP / TIMEOUT. FAIL means an
AssertionError and nothing else: any error, crash, import failure, mismatch
between the parsed sections and unittest's own summary, or unparseable output
is ERROR. An ERROR never counts as a FAIL.

Every run asserts in-process that ``django.__file__`` lives inside the worktree;
a wrong tree raises :class:`WrongTreeError` rather than producing an outcome.
"""

from __future__ import annotations

import json
import os
import re
import signal
import subprocess
import tempfile
import time
from collections.abc import Sequence
from dataclasses import dataclass, field
from pathlib import Path
from typing import Literal

Outcome = Literal["PASS", "FAIL", "ERROR", "SKIP", "TIMEOUT"]

SHIM = Path(__file__).with_name("_runtests_shim.py")
WRONG_TREE_EXIT = 97
DJANGO_FILE_MARK = "HEIRLOOM_DJANGO_FILE="

_ID = r"(?P<name>\w+) \((?P<id>[\w.]+)\)"
_STATUS = r"(?P<status>ok|FAIL|ERROR|skipped(?: .*)?|expected failure|unexpected success)"
STATUS_LINE = re.compile(rf"^{_ID} \.\.\. {_STATUS}$")
ID_ONLY_LINE = re.compile(rf"^{_ID}$")
TRAILING_STATUS = re.compile(rf"^.* \.\.\. {_STATUS}$")
SECTION = re.compile(rf"^(?P<kind>FAIL|ERROR): {_ID}(?: \((?P<sub>.*)\))?$")
RAN = re.compile(r"^Ran (?P<n>\d+) tests? in [\d.]+s$")
SUMMARY = re.compile(r"^(?P<word>OK|FAILED)(?: \((?P<counts>[^)]*)\))?$")
ASSERTION = re.compile(r"^(?:[\w.]+\.)?\w*AssertionError\b")

_STATUS_MAP: dict[str, Outcome] = {
    "ok": "PASS",
    "FAIL": "FAIL",
    "ERROR": "ERROR",
    "expected failure": "ERROR",
    "unexpected success": "ERROR",
}


class WrongTreeError(RuntimeError):
    pass


@dataclass(frozen=True)
class TestOutcome:
    outcome: Outcome
    detail: str = ""


@dataclass
class RunResult:
    outcome: Outcome
    tests: dict[str, TestOutcome]
    ran: int
    summary: str
    harness_errors: list[str] = field(default_factory=list)
    reason: str = ""
    returncode: int | None = None
    seconds: float = 0.0
    django_file: str = ""
    log_path: Path | None = None
    coverage: dict[str, set[int]] = field(default_factory=dict)

    def ids(self, outcome: Outcome) -> frozenset[str]:
        return frozenset(t for t, o in self.tests.items() if o.outcome == outcome)

    @property
    def failing_ids(self) -> frozenset[str]:
        return self.ids("FAIL")

    @property
    def error_ids(self) -> frozenset[str]:
        return self.ids("ERROR")

    @property
    def skipped_ids(self) -> frozenset[str]:
        return self.ids("SKIP")

    def to_json(self) -> dict[str, object]:
        return {
            "outcome": self.outcome,
            "ran": self.ran,
            "summary": self.summary,
            "reason": self.reason,
            "harness_errors": self.harness_errors,
            "failing_ids": sorted(self.failing_ids),
            "error_ids": sorted(self.error_ids),
            "skipped_ids": sorted(self.skipped_ids),
            "tests": {k: [v.outcome, v.detail] for k, v in sorted(self.tests.items())},
            "seconds": round(self.seconds, 2),
            "django_file": self.django_file,
            "log": str(self.log_path) if self.log_path else None,
        }


def _section_details(lines: Sequence[str]) -> list[tuple[str, str, str, str]]:
    """Return (kind, name, id, exception line) for each FAIL/ERROR section."""
    out: list[tuple[str, str, str, str]] = []
    i = 0
    while i < len(lines):
        m = SECTION.match(lines[i])
        if not m:
            i += 1
            continue
        j = i + 1
        exc = ""
        while j < len(lines) and not lines[j].startswith(("=" * 20, "Ran ")):
            if lines[j].startswith("-" * 20) and j > i + 1:
                break
            text = lines[j]
            if text and not text.startswith((" ", "Traceback", "-" * 20)):
                exc = exc or text
                if not text.startswith(("During handling", "The above exception")):
                    exc = text
            j += 1
        out.append((m["kind"], m["name"], m["id"], exc))
        i = j
    return out


def _counts(text: str | None) -> dict[str, int]:
    counts: dict[str, int] = {}
    for part in (text or "").split(","):
        if "=" in part:
            k, v = part.strip().split("=", 1)
            counts[k.strip()] = int(v)
    return counts


def classify(stderr: str, *, returncode: int | None, timed_out: bool = False) -> RunResult:
    """Classify unittest ``-v 2`` output (stderr of runtests.py)."""
    lines = stderr.splitlines()
    tests: dict[str, TestOutcome] = {}
    pending: str | None = None
    for line in lines:
        m = STATUS_LINE.match(line)
        if m:
            tests[m["id"]] = TestOutcome(_status(m["status"]), _skip_reason(m["status"]))
            pending = None
            continue
        m = ID_ONLY_LINE.match(line)
        if m and m["name"].startswith("test"):
            pending = m["id"]
            continue
        if pending:
            t = TRAILING_STATUS.match(line)
            if t:
                tests[pending] = TestOutcome(_status(t["status"]), _skip_reason(t["status"]))
                pending = None

    harness_errors: list[str] = []
    n_fail = n_error = 0
    for kind, name, test_id, exc in _section_details(lines):
        is_test = name.startswith("test") and "unittest.loader." not in test_id
        if kind == "FAIL":
            n_fail += 1
        else:
            n_error += 1
        if not is_test:
            harness_errors.append(f"{kind}: {name} ({test_id}): {exc}")
            continue
        if kind == "FAIL" and ASSERTION.match(exc):
            if tests.get(test_id, TestOutcome("PASS")).outcome != "ERROR":
                tests[test_id] = TestOutcome("FAIL", exc)
        else:
            # An ERROR, or a FAIL that is not an AssertionError, is never a FAIL.
            tests[test_id] = TestOutcome("ERROR", exc or kind)

    ran_n = -1
    summary = ""
    summary_counts: dict[str, int] = {}
    for line in lines:
        r = RAN.match(line)
        if r:
            ran_n = int(r["n"])
        s = SUMMARY.match(line)
        if s and ran_n >= 0:
            summary = line
            summary_counts = _counts(s["counts"])

    def result(outcome: Outcome, reason: str = "") -> RunResult:
        return RunResult(
            outcome=outcome,
            tests=tests,
            ran=max(ran_n, 0),
            summary=summary,
            harness_errors=harness_errors,
            reason=reason,
            returncode=returncode,
        )

    if timed_out:
        return result("TIMEOUT", "timed out")
    if ran_n < 0 or not summary:
        return result("ERROR", "no unittest summary (crash or import failure)")
    if ran_n == 0:
        return result("ERROR", "no tests ran")
    if summary_counts.get("failures", 0) != n_fail or summary_counts.get("errors", 0) != n_error:
        return result("ERROR", f"sections ({n_fail}F/{n_error}E) disagree with '{summary}'")
    if summary.startswith("OK") != (returncode == 0):
        return result("ERROR", f"summary '{summary}' disagrees with exit code {returncode}")
    if harness_errors or any(t.outcome == "ERROR" for t in tests.values()):
        return result("ERROR", "errors present")
    if any(t.outcome == "FAIL" for t in tests.values()):
        return result("FAIL")
    if tests and all(t.outcome == "SKIP" for t in tests.values()):
        return result("SKIP", "all tests skipped")
    return result("PASS")


def _status(status: str) -> Outcome:
    return "SKIP" if status.startswith("skipped") else _STATUS_MAP[status]


def _skip_reason(status: str) -> str:
    return status[len("skipped ") :].strip("'") if status.startswith("skipped ") else ""


@dataclass(frozen=True)
class Runner:
    python: Path
    timeout: float = 900.0
    extra_pythonpath: tuple[Path, ...] = ()

    def run(
        self,
        worktree: Path,
        labels: Sequence[str],
        *,
        log_path: Path,
        extra_args: Sequence[str] = (),
        coverage_include: Sequence[Path] = (),
    ) -> RunResult:
        wt = worktree.resolve()
        log_path.parent.mkdir(parents=True, exist_ok=True)
        env = {k: v for k, v in os.environ.items() if k not in ("PYTHONPATH", "VIRTUAL_ENV")}
        env["PYTHONPATH"] = os.pathsep.join([str(wt), *map(str, self.extra_pythonpath)])
        env["PYTHONDONTWRITEBYTECODE"] = "1"
        args = [*labels, "--parallel=1", "-v", "2", *extra_args]
        cov_file: Path | None = None
        if coverage_include:
            fd, name = tempfile.mkstemp(prefix="hl-cov-", dir=log_path.parent)
            os.close(fd)
            cov_file = Path(name)
            include = ",".join(str(p.resolve()) for p in coverage_include)
            cmd = [
                str(self.python),
                "-m",
                "coverage",
                "run",
                f"--data-file={cov_file}",
                f"--include={include}",
                str(SHIM),
                str(wt),
                *args,
            ]
        else:
            cmd = [str(self.python), str(SHIM), str(wt), *args]
        start = time.monotonic()
        proc = subprocess.Popen(
            cmd,
            cwd=wt / "tests",
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            start_new_session=True,
        )
        timed_out = False
        try:
            out, err = proc.communicate(timeout=self.timeout)
        except subprocess.TimeoutExpired:
            timed_out = True
            os.killpg(proc.pid, signal.SIGKILL)
            out, err = proc.communicate()
        seconds = time.monotonic() - start
        log_path.write_text(
            f"$ {' '.join(cmd)}\n# cwd={wt / 'tests'} PYTHONPATH={env['PYTHONPATH']}\n"
            f"# exit={proc.returncode} seconds={seconds:.1f}\n"
            f"--- stdout ---\n{out}\n--- stderr ---\n{err}"
        )
        if proc.returncode == WRONG_TREE_EXIT or DJANGO_FILE_MARK not in out:
            raise WrongTreeError(f"django is not imported from {wt}; see {log_path}")
        django_file = out.split(DJANGO_FILE_MARK, 1)[1].splitlines()[0].strip()
        if not django_file.startswith(str(wt) + os.sep):
            raise WrongTreeError(f"django imported from {django_file}, expected inside {wt}")
        res = classify(err, returncode=proc.returncode, timed_out=timed_out)
        res.seconds = seconds
        res.django_file = django_file
        res.log_path = log_path
        if cov_file is not None:
            res.coverage = self._coverage(cov_file, wt)
            for suffix in ("", ".json"):
                Path(f"{cov_file}{suffix}").unlink(missing_ok=True)
        return res

    def _coverage(self, data_file: Path, wt: Path) -> dict[str, set[int]]:
        json_path = Path(f"{data_file}.json")
        subprocess.run(
            [
                str(self.python),
                "-m",
                "coverage",
                "json",
                "-q",
                f"--data-file={data_file}",
                "-o",
                str(json_path),
            ],
            check=True,
            capture_output=True,
        )
        files = json.loads(json_path.read_text())["files"]
        out: dict[str, set[int]] = {}
        for name, data in files.items():
            path = Path(name)
            rel = path.resolve().relative_to(wt) if path.is_absolute() else path
            out[str(rel)] = set(data["executed_lines"])
        return out

"""Thin, explicit git helpers (subprocess, no shell)."""

from __future__ import annotations

import re
import subprocess
from dataclasses import dataclass, field
from pathlib import Path


class GitError(RuntimeError):
    pass


def git(repo: Path, *args: str, check: bool = True, input: str | None = None) -> str:
    proc = subprocess.run(
        ["git", "-C", str(repo), *args], capture_output=True, text=True, input=input
    )
    if check and proc.returncode != 0:
        raise GitError(f"git {' '.join(args)} failed ({proc.returncode}): {proc.stderr.strip()}")
    return proc.stdout


def git_ok(repo: Path, *args: str) -> bool:
    return subprocess.run(["git", "-C", str(repo), *args], capture_output=True).returncode == 0


def rev_parse(repo: Path, ref: str) -> str:
    return git(repo, "rev-parse", "--verify", f"{ref}^{{commit}}").strip()


def is_ancestor(repo: Path, ancestor: str, descendant: str) -> bool:
    return git_ok(repo, "merge-base", "--is-ancestor", ancestor, descendant)


def show_file(repo: Path, ref: str, path: str) -> str | None:
    proc = subprocess.run(
        ["git", "-C", str(repo), "show", f"{ref}:{path}"], capture_output=True, text=True
    )
    return proc.stdout if proc.returncode == 0 else None


def ensure_worktree(repo: Path, path: Path, commit: str) -> Path:
    """Create (or reset) a detached worktree at ``commit``; idempotent."""
    if path.exists():
        if git_ok(path, "rev-parse", "--git-dir"):
            git(path, "checkout", "-q", "--detach", "-f", commit)
            git(path, "reset", "-q", "--hard", commit)
            git(path, "clean", "-q", "-fdx", "-e", ".claude/", "-e", ".entire/")
            return path
        raise GitError(f"{path} exists and is not a worktree")
    path.parent.mkdir(parents=True, exist_ok=True)
    git(repo, "worktree", "prune")
    git(repo, "worktree", "add", "-q", "--detach", str(path), commit)
    return path


def remove_worktree(repo: Path, path: Path) -> None:
    if path.exists():
        git(repo, "worktree", "remove", "--force", str(path), check=False)
    git(repo, "worktree", "prune")


# Diffs -------------------------------------------------------------------------

HUNK = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@")


@dataclass
class Hunk:
    old_start: int
    old_count: int
    new_start: int
    new_count: int
    removed: list[str] = field(default_factory=list)
    added: list[str] = field(default_factory=list)


@dataclass
class FileDiff:
    old_path: str | None
    new_path: str | None
    hunks: list[Hunk] = field(default_factory=list)

    @property
    def path(self) -> str:
        return self.new_path or self.old_path or ""


def parse_diff(text: str) -> list[FileDiff]:
    files: list[FileDiff] = []
    cur: FileDiff | None = None
    hunk: Hunk | None = None
    for line in text.splitlines():
        if line.startswith("diff --git "):
            cur = FileDiff(None, None)
            files.append(cur)
            hunk = None
        elif cur is None:
            continue
        elif line.startswith("--- ") and hunk is None:
            p = line[4:]
            cur.old_path = None if p == "/dev/null" else p.removeprefix("a/")
        elif line.startswith("+++ ") and hunk is None:
            p = line[4:]
            cur.new_path = None if p == "/dev/null" else p.removeprefix("b/")
        elif m := HUNK.match(line):
            hunk = Hunk(
                int(m[1]),
                int(m[2]) if m[2] is not None else 1,
                int(m[3]),
                int(m[4]) if m[4] is not None else 1,
            )
            cur.hunks.append(hunk)
        elif hunk is not None and line.startswith("-"):
            hunk.removed.append(line[1:])
        elif hunk is not None and line.startswith("+"):
            hunk.added.append(line[1:])
    return files


def commit_diff(repo: Path, sha: str, *paths: str, context: int = 0) -> str:
    return git(repo, "diff", f"-U{context}", "-M", f"{sha}^", sha, "--", *paths)

"""PRESENCE: the calibration verdict table (BUILD-BRIEF §3.4, with §9 fixes).

Pure functions over executed evidence. Nothing here asks a model anything.

| Verdict             | Condition                                                          |
|---------------------|--------------------------------------------------------------------|
| AFFECTED            | C1 ∧ C2 ∧ C3 ∧ probe FAILs on L with the same failing ids as on U⁻ |
| NOT_AFFECTED_PROVEN | C1 ∧ C2 ∧ 3× PASS on L ∧ ((C3 ∧ (C4a ∨ C4b caught it)) ∨ C4c)      |
| UNPROVEN            | anything else, with a reason code                                  |
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Literal

from heirloom.verify.runner import Outcome, RunResult

Verdict = Literal["AFFECTED", "NOT_AFFECTED_PROVEN", "UNPROVEN"]
Reason = Literal[
    "STRUCTURAL_TEST",
    "NON_DISCRIMINATING",
    "PROBE_ERROR",
    "ENV_SKIP",
    "FLAKY",
    "NO_REACH",
    "MUTANT_SURVIVED",
    "MUTANT_UNBUILDABLE",
    "FAIL_MISMATCH",
]
MutantMethod = Literal["reverse_apply", "added_condition", "transplant"]


@dataclass(frozen=True)
class ProbeRun:
    outcome: Outcome
    failing_ids: frozenset[str] = frozenset()
    skipped_ids: frozenset[str] = frozenset()

    @classmethod
    def of(cls, result: RunResult) -> ProbeRun:
        return cls(result.outcome, result.failing_ids, result.skipped_ids)


@dataclass(frozen=True)
class Gate:
    ok: bool
    reason: Reason | None = None
    detail: str = ""


@dataclass(frozen=True)
class MutantOutcome:
    """C4a/C4b: one attempt to rebuild the vulnerability inside L."""

    method: MutantMethod
    built: bool
    probe: ProbeRun | None = None
    detail: str = ""

    @property
    def works(self) -> bool:
        # A mutant "works" if it builds and the probe runs on it (PASS or FAIL).
        # A probe ERROR on the mutant is not a catch; the mutant is unusable.
        return self.built and self.probe is not None and self.probe.outcome in ("PASS", "FAIL")

    @property
    def caught(self) -> bool:
        return self.works and self.probe is not None and self.probe.outcome == "FAIL"


@dataclass(frozen=True)
class Evidence:
    um: tuple[ProbeRun, ...]
    up: tuple[ProbeRun, ...]
    l: tuple[ProbeRun, ...]
    reach: Gate
    mutants: tuple[MutantOutcome, ...] = ()
    provenance: Gate | None = None


@dataclass(frozen=True)
class Presence:
    verdict: Verdict
    reason: Reason | None
    gates: dict[str, Gate] = field(default_factory=dict)
    detail: str = ""

    @property
    def calibrated(self) -> bool:
        return self.verdict != "UNPROVEN"


def _unusable(runs: tuple[ProbeRun, ...], where: str) -> Gate | None:
    if not runs:
        return Gate(False, "PROBE_ERROR", f"no runs on {where}")
    if any(r.outcome in ("ERROR", "TIMEOUT") for r in runs):
        return Gate(False, "PROBE_ERROR", f"probe ERROR/TIMEOUT on {where}")
    if any(r.outcome == "SKIP" or r.skipped_ids for r in runs):
        return Gate(False, "ENV_SKIP", f"probe skipped on {where}")
    if len({r.outcome for r in runs}) > 1:
        return Gate(False, "FLAKY", f"outcomes differ across runs on {where}")
    if runs[0].outcome == "FAIL" and len({r.failing_ids for r in runs}) > 1:
        return Gate(False, "FLAKY", f"failing ids differ across runs on {where}")
    return None


def c1_discrimination(e: Evidence) -> Gate:
    bad = _unusable(e.um, "U⁻") or _unusable(e.up, "U⁺")
    if bad:
        return bad
    if e.um[0].outcome != "FAIL" or not e.um[0].failing_ids:
        return Gate(False, "NON_DISCRIMINATING", "probe does not FAIL on U⁻")
    if e.up[0].outcome != "PASS":
        return Gate(False, "NON_DISCRIMINATING", "probe does not PASS on U⁺")
    return Gate(True, detail=f"{len(e.um[0].failing_ids)} stable failing ids on U⁻")


def c2_portability(e: Evidence) -> Gate:
    return _unusable(e.l, "L") or Gate(True)


def c4_sensitivity(e: Evidence) -> Gate:
    """C4a ∨ C4b: the first mutant that works decides."""
    for m in e.mutants:
        if m.works:
            if m.caught:
                return Gate(True, detail=f"{m.method} mutant caught")
            return Gate(False, "MUTANT_SURVIVED", f"{m.method} mutant survived: {m.detail}")
    tried = ", ".join(f"{m.method}: {m.detail}" for m in e.mutants) or "none"
    return Gate(False, "MUTANT_UNBUILDABLE", f"no working mutant ({tried})")


def presence(e: Evidence) -> Presence:
    gates: dict[str, Gate] = {}
    c1 = gates["C1"] = c1_discrimination(e)
    if not c1.ok:
        return Presence("UNPROVEN", c1.reason, gates, c1.detail)
    c2 = gates["C2"] = c2_portability(e)
    if not c2.ok:
        return Presence("UNPROVEN", c2.reason, gates, c2.detail)
    gates["C3"] = e.reach
    l_outcome = e.l[0].outcome

    if l_outcome == "FAIL":
        if not e.reach.ok:
            return Presence("UNPROVEN", "NO_REACH", gates, e.reach.detail)
        if e.l[0].failing_ids != e.um[0].failing_ids:
            return Presence(
                "UNPROVEN", "FAIL_MISMATCH", gates, "failing ids on L differ from U⁻"
            )
        return Presence("AFFECTED", None, gates, "probe FAILs on L with U⁻'s failing ids")

    # Probe PASSes 3× on L: only executed sensitivity or recursive provenance proves it.
    c4 = gates["C4ab"] = c4_sensitivity(e)
    c4c = gates["C4c"] = e.provenance or Gate(False, None, "not run")
    if (e.reach.ok and c4.ok) or c4c.ok:
        why = c4.detail if (e.reach.ok and c4.ok) else c4c.detail
        return Presence("NOT_AFFECTED_PROVEN", None, gates, why)
    if not e.reach.ok:
        return Presence("UNPROVEN", "NO_REACH", gates, e.reach.detail)
    return Presence("UNPROVEN", c4.reason, gates, c4.detail)

"""CALIBRATE: evidence for gates C3 (reach) and C4 (sensitivity, provenance).

The orchestration that runs the probe 3× on U⁻/U⁺/L lives in
``heirloom.pipeline.stages``; this module holds the deterministic machinery:

* ``enclosing_symbols`` / ``map_symbol``: C3 symbol mapping (ast on U⁻ → L).
* ``added_condition_mutant``: C4b fallback (§9) that removes boolean operands
  the fix added, instead of transplanting 5.x-only internals.
* ``transplant``: C4b proper, U⁻'s version of a symbol pasted into L (libcst).
* ``provenance``: C4c with recursive blame through line modifications (§9).
"""

from __future__ import annotations

import ast
import difflib
import re
from collections.abc import Iterable, Sequence
from dataclasses import dataclass
from pathlib import Path

import libcst as cst

from heirloom.git_ops import FileDiff, commit_diff, git, git_ok, is_ancestor, parse_diff
from heirloom.pipeline.presence import Gate

# C3 · reach -------------------------------------------------------------------


@dataclass(frozen=True)
class Symbol:
    qualname: str
    start: int  # first line incl. decorators
    end: int
    body_start: int


def symbols(source: str) -> list[Symbol]:
    out: list[Symbol] = []

    def walk(node: ast.AST, prefix: str) -> None:
        for child in ast.iter_child_nodes(node):
            if isinstance(child, ast.FunctionDef | ast.AsyncFunctionDef | ast.ClassDef):
                q = f"{prefix}{child.name}"
                start = min([child.lineno, *(d.lineno for d in child.decorator_list)])
                end = child.end_lineno or child.lineno
                out.append(Symbol(q, start, end, child.body[0].lineno))
                walk(child, q + ".")

    walk(ast.parse(source), "")
    return out


def enclosing_symbols(source: str, lines: Iterable[int]) -> list[str]:
    """Innermost function (or class, if no function) enclosing each line."""
    syms = symbols(source)
    found: list[str] = []
    for ln in lines:
        inside = [s for s in syms if s.start <= ln <= s.end]
        if not inside:
            continue
        best = max(inside, key=lambda s: s.start)
        if best.qualname not in found:
            found.append(best.qualname)
    return found


def fix_hunk_lines(diff: FileDiff) -> list[int]:
    """Old-side (U⁻) line numbers touched by each hunk; insertions anchor on the line above."""
    lines: list[int] = []
    for h in diff.hunks:
        if h.old_count:
            lines.extend(range(h.old_start, h.old_start + h.old_count))
        else:
            lines.append(max(h.old_start, 1))
    return lines


@dataclass(frozen=True)
class MappedSymbol:
    um_path: str
    qualname: str
    l_path: str | None
    l_symbol: Symbol | None
    how: str  # same-path | rename | search | absent


def map_symbol(repo: Path, l_ref: str, um_ref: str, path: str, qualname: str) -> MappedSymbol:
    """Map a U⁻ symbol to L: same module+qualname, then rename tracking, then a search."""
    from heirloom.git_ops import show_file

    src = show_file(repo, l_ref, path)
    if src is not None:
        sym = next((s for s in symbols(src) if s.qualname == qualname), None)
        if sym:
            return MappedSymbol(path, qualname, path, sym, "same-path")
    renamed = git(
        repo, "diff", "--name-status", "-M", l_ref, um_ref, "--diff-filter=R", check=False
    )
    for row in renamed.splitlines():
        parts = row.split("\t")
        if len(parts) == 3 and parts[2] == path:
            src = show_file(repo, l_ref, parts[1])
            sym = next((s for s in symbols(src or "") if s.qualname == qualname), None)
            if sym:
                return MappedSymbol(path, qualname, parts[1], sym, "rename")
    name = qualname.rsplit(".", 1)[-1]
    hits = git(repo, "grep", "-l", "-E", rf"def {re.escape(name)}\(", l_ref, "--", "django/", check=False)
    for hit in hits.splitlines():
        hit_path = hit.split(":", 1)[1]
        src = show_file(repo, l_ref, hit_path)
        sym = next((s for s in symbols(src or "") if s.qualname == qualname), None)
        if sym:
            return MappedSymbol(path, qualname, hit_path, sym, "search")
    return MappedSymbol(path, qualname, None, None, "absent")


def reach_gate(mapped: Sequence[MappedSymbol], covered: dict[str, set[int]]) -> Gate:
    """C3: coverage on L hits ≥1 body line of every mapped symbol present in L."""
    present = [m for m in mapped if m.l_symbol is not None and m.l_path is not None]
    if not present:
        return Gate(False, "NO_REACH", "no fix symbol exists in L")
    missed: list[str] = []
    for m in present:
        assert m.l_symbol is not None and m.l_path is not None
        body = set(range(m.l_symbol.body_start, m.l_symbol.end + 1))
        if not body & covered.get(m.l_path, set()):
            missed.append(m.qualname)
    if missed:
        return Gate(False, "NO_REACH", f"probe never executed {', '.join(missed)} on L")
    names = ", ".join(f"{m.qualname} ({m.how})" for m in present)
    return Gate(True, detail=f"reached {names}")


# C4b · mutants ------------------------------------------------------------------

_CONDITION = re.compile(r"^\s*(?:if|elif|while|return|assert)\s+(.*?):?\s*$")


def _expr(line: str) -> cst.BaseExpression | None:
    m = _CONDITION.match(line)
    text = m[1] if m else line.strip().rstrip(":")
    try:
        return cst.parse_expression(text)
    except cst.ParserSyntaxError:
        return None


def _code(node: cst.CSTNode) -> str:
    return " ".join(cst.Module(body=[]).code_for_node(node).split())


def _flatten(node: cst.BaseExpression, op: type[cst.BaseBooleanOp]) -> list[cst.BaseExpression]:
    if isinstance(node, cst.BooleanOperation) and isinstance(node.operator, op):
        return [*_flatten(node.left, op), *_flatten(node.right, op)]
    return [node]


def added_operands(diff: FileDiff) -> list[tuple[str, str]]:
    """Boolean operands the fix added to an existing condition, as (op, code).

    Only hunks that replace a condition with a superset of its operands qualify,
    e.g. ``if not obj._is_pk_set():`` → ``if not obj._is_pk_set() or obj._state.adding:``.
    """
    found: list[tuple[str, str]] = []
    for h in diff.hunks:
        olds = [e for e in (_expr(x) for x in h.removed) if e is not None]
        news = [e for e in (_expr(x) for x in h.added) if e is not None]
        for new in news:
            if not isinstance(new, cst.BooleanOperation):
                continue
            op_type: type[cst.BaseBooleanOp] = type(new.operator)
            op_name = "or" if isinstance(new.operator, cst.Or) else "and"
            new_ops = [_code(x) for x in _flatten(new, op_type)]
            for old in olds:
                old_ops = [_code(x) for x in _flatten(old, op_type)]
                extra = [x for x in new_ops if x not in old_ops]
                if extra and all(x in new_ops for x in old_ops):
                    found.extend((op_name, x) for x in extra)
    return found


class _DropOperands(cst.CSTTransformer):
    def __init__(self, operands: set[str]) -> None:
        self.operands = operands
        self.removed = 0

    def leave_BooleanOperation(
        self, original: cst.BooleanOperation, updated: cst.BooleanOperation
    ) -> cst.BaseExpression:
        op_type: type[cst.BaseBooleanOp] = type(updated.operator)
        parts = _flatten(updated, op_type)
        keep = [p for p in parts if _code(p) not in self.operands]
        if len(keep) == len(parts) or not keep:
            return updated
        self.removed += len(parts) - len(keep)
        result = keep[0]
        for p in keep[1:]:
            result = cst.BooleanOperation(left=result, operator=updated.operator, right=p)
        return result


class _InSymbol(cst.CSTTransformer):
    """Apply ``inner`` only inside the function/class at ``qualname``."""

    def __init__(self, qualname: str, inner: cst.CSTTransformer) -> None:
        self.target = qualname.split(".")
        self.stack: list[str] = []
        self.inner = inner

    def visit_ClassDef(self, node: cst.ClassDef) -> None:
        self.stack.append(node.name.value)

    def leave_ClassDef(self, original: cst.ClassDef, updated: cst.ClassDef) -> cst.ClassDef:
        self.stack.pop()
        return updated

    def visit_FunctionDef(self, node: cst.FunctionDef) -> bool:
        self.stack.append(node.name.value)
        return self.stack != self.target

    def leave_FunctionDef(
        self, original: cst.FunctionDef, updated: cst.FunctionDef
    ) -> cst.FunctionDef:
        if self.stack == self.target:
            updated = updated.visit(self.inner)  # type: ignore[assignment]
        self.stack.pop()
        return updated


def added_condition_mutant(
    source: str, qualnames: Sequence[str], operands: Sequence[tuple[str, str]]
) -> str | None:
    """L's source with the fix's added operands removed inside the mapped symbols."""
    if not operands:
        return None
    module = cst.parse_module(source)
    dropper = _DropOperands({code for _, code in operands})
    for q in qualnames:
        module = module.visit(_InSymbol(q, dropper))
    return module.code if dropper.removed else None


class _Transplant(cst.CSTTransformer):
    def __init__(self, qualname: str, donor: cst.FunctionDef) -> None:
        self.target = qualname.split(".")
        self.stack: list[str] = []
        self.donor = donor
        self.done = 0

    def visit_ClassDef(self, node: cst.ClassDef) -> None:
        self.stack.append(node.name.value)

    def leave_ClassDef(self, original: cst.ClassDef, updated: cst.ClassDef) -> cst.ClassDef:
        self.stack.pop()
        return updated

    def visit_FunctionDef(self, node: cst.FunctionDef) -> bool:
        self.stack.append(node.name.value)
        return False

    def leave_FunctionDef(
        self, original: cst.FunctionDef, updated: cst.FunctionDef
    ) -> cst.FunctionDef:
        hit = self.stack == self.target
        self.stack.pop()
        if hit:
            self.done += 1
            return self.donor
        return updated


def _find_function(module: cst.Module, qualname: str) -> cst.FunctionDef | None:
    parts = qualname.split(".")
    body: Sequence[cst.CSTNode] = module.body
    for i, name in enumerate(parts):
        last = i == len(parts) - 1
        nxt: cst.CSTNode | None = None
        for node in body:
            if last and isinstance(node, cst.FunctionDef) and node.name.value == name:
                return node
            if not last and isinstance(node, cst.ClassDef) and node.name.value == name:
                nxt = node
        if not isinstance(nxt, cst.ClassDef) or not isinstance(nxt.body, cst.IndentedBlock):
            return None
        body = nxt.body.body
    return None


def transplant(target: str, donor: str, qualnames: Sequence[str]) -> str | None:
    """Replace each function in ``qualnames`` in ``target`` with ``donor``'s version."""
    module = cst.parse_module(target)
    donor_module = cst.parse_module(donor)
    changed = 0
    for q in qualnames:
        fn = _find_function(donor_module, q)
        if fn is None:
            return None
        t = _Transplant(q, fn)
        module = module.visit(t)
        changed += t.done
    return module.code if changed else None


# C4c · recursive provenance -------------------------------------------------------


@dataclass(frozen=True)
class Origin:
    line: str
    chain: tuple[str, ...]  # blame commits walked, newest first
    origin: str | None  # commit that added the line (pure addition), None if unresolved
    detail: str


def _blame(repo: Path, rev: str, path: str, line: int) -> tuple[str, str, int]:
    out = git(repo, "blame", "-w", "-M", "--porcelain", "-L", f"{line},{line}", rev, "--", path)
    head = out.splitlines()[0].split()
    sha, orig_line = head[0], int(head[1])
    orig_path = path
    for row in out.splitlines():
        if row.startswith("filename "):
            orig_path = row[len("filename ") :]
    return sha, orig_path, orig_line


def trace_origin(repo: Path, rev: str, path: str, line: int, *, max_depth: int = 25) -> Origin:
    """Follow blame through commits that *modified* the line until a pure addition."""
    text = (git(repo, "show", f"{rev}:{path}").splitlines() or [""])[line - 1]
    chain: list[str] = []
    for _ in range(max_depth):
        sha, cpath, cline = _blame(repo, rev, path, line)
        chain.append(sha)
        if not git_ok(repo, "rev-parse", "--verify", f"{sha}^"):
            return Origin(text, tuple(chain), sha, "root commit")
        diff = next((f for f in parse_diff(commit_diff(repo, sha)) if f.new_path == cpath), None)
        hunk = None
        if diff is not None:
            hunk = next(
                (h for h in diff.hunks if h.new_start <= cline < h.new_start + h.new_count), None
            )
        if diff is None or hunk is None:
            return Origin(text, tuple(chain), None, f"no hunk for {cpath}:{cline} in {sha[:10]}")
        if not hunk.removed:
            return Origin(text, tuple(chain), sha, f"added by {sha[:10]}")
        # Modification: recurse on the most similar predecessor line in the parent.
        new_line = hunk.added[cline - hunk.new_start]
        ratios = [
            difflib.SequenceMatcher(None, new_line.strip(), r.strip()).ratio()
            for r in hunk.removed
        ]
        idx = max(range(len(ratios)), key=ratios.__getitem__)
        rev, path, line = f"{sha}^", diff.old_path or cpath, hunk.old_start + idx
    return Origin(text, tuple(chain), None, "provenance chain too deep")


def changed_lines(diff: FileDiff) -> list[int]:
    """U⁻ line numbers the fix deletes or changes (pure insertions have none)."""
    out: list[int] = []
    for h in diff.hunks:
        if h.removed:
            out.extend(range(h.old_start, h.old_start + h.old_count))
    return out


def provenance(
    repo: Path,
    um_ref: str,
    l_ref: str,
    fix_diffs: Sequence[FileDiff],
    l_symbol_text: str,
) -> Gate:
    """C4c: every changed line was *introduced* after the branch point and never backported."""
    base = git(repo, "merge-base", um_ref, l_ref).strip()
    lines = [(d.old_path or d.path, n) for d in fix_diffs for n in changed_lines(d)]
    if not lines:
        return Gate(False, None, "fix only inserts lines; provenance cannot apply")
    l_text = " ".join(l_symbol_text.split())
    for path, n in lines:
        o = trace_origin(repo, um_ref, path, n)
        if o.origin is None:
            return Gate(False, None, f"{path}:{n}: {o.detail}")
        if is_ancestor(repo, o.origin, base):
            return Gate(
                False,
                None,
                f"{path}:{n} traces to {o.origin[:10]} (via {len(o.chain)} commits), "
                f"an ancestor of merge-base {base[:10]}",
            )
        backports = git(repo, "log", "--format=%H", f"--grep=Backport of {o.origin}", f"{base}..{l_ref}")
        if backports.strip():
            return Gate(False, None, f"{o.origin[:10]} was backported to L")
        if " ".join(o.line.split()) and " ".join(o.line.split()) in l_text:
            return Gate(False, None, f"line text of {path}:{n} present in L")
    return Gate(True, detail=f"{len(lines)} changed lines introduced after {base[:10]}")

