"""LiteLLM calls through the gateway, with a hard per-CVE budget.

``litellm`` is imported lazily so ``neatlogs.init()`` can run first and
instrument it. The gateway reports ``totalCostUsd: 0``, so cost is computed
here from token usage at list prices (estimates, recorded on every span).
"""

from __future__ import annotations

from collections.abc import Callable, Sequence
from dataclasses import dataclass
from typing import Any

from heirloom.config import Settings

# USD per million tokens (input, output): Anthropic list prices for the
# Sonnet 4.x and Haiku 4.5 tiers; Amazon Nova Lite list price.
PRICES: dict[str, tuple[float, float]] = {
    "claude-sonnet-4.6": (3.0, 15.0),
    "claude-haiku": (1.0, 5.0),
    "nova-lite": (0.06, 0.24),
}
OPENROUTER_MODELS = {"claude-sonnet-4.6": "anthropic/claude-sonnet-4.6"}


class BudgetExceeded(RuntimeError):
    pass


@dataclass
class Budget:
    limit_usd: float
    spent: Callable[[], float]

    def remaining(self) -> float:
        return self.limit_usd - self.spent()

    def check(self, needed: float = 0.0) -> None:
        if self.remaining() <= needed:
            raise BudgetExceeded(
                f"budget exhausted: spent ${self.spent():.4f} of ${self.limit_usd:.2f}"
            )


@dataclass(frozen=True)
class Completion:
    text: str
    model: str
    input_tokens: int
    output_tokens: int
    cost_usd: float
    provider: str


def cost_of(model: str, input_tokens: int, output_tokens: int) -> float:
    pin, pout = PRICES.get(model, PRICES["claude-sonnet-4.6"])
    return (input_tokens * pin + output_tokens * pout) / 1_000_000


class Router:
    def __init__(self, settings: Settings, budget: Budget) -> None:
        self.settings = settings
        self.budget = budget

    def complete(
        self,
        model: str,
        messages: Sequence[dict[str, str]],
        *,
        max_tokens: int = 4096,
        temperature: float = 0.0,
    ) -> Completion:
        self.budget.check()
        import litellm

        attempts: list[tuple[str, dict[str, Any]]] = [
            (
                "litellm-gateway",
                {
                    "model": f"openai/{model}",
                    "api_base": self.settings.litellm_base,
                    "api_key": self.settings.litellm_key,
                },
            )
        ]
        if self.settings.openrouter_key and model in OPENROUTER_MODELS:
            attempts.append(
                (
                    "openrouter",
                    {
                        "model": f"openrouter/{OPENROUTER_MODELS[model]}",
                        "api_key": self.settings.openrouter_key,
                    },
                )
            )
        last: Exception | None = None
        for provider, kw in attempts:
            try:
                resp = litellm.completion(
                    messages=list(messages),
                    max_tokens=max_tokens,
                    temperature=temperature,
                    timeout=600,
                    **kw,
                )
            except Exception as exc:  # gateway down or rate limited: try overflow
                last = exc
                continue
            usage = resp.usage
            cost = cost_of(model, int(usage.prompt_tokens), int(usage.completion_tokens))
            return Completion(
                text=str(resp.choices[0].message.content or ""),
                model=model,
                input_tokens=int(usage.prompt_tokens),
                output_tokens=int(usage.completion_tokens),
                cost_usd=cost,
                provider=provider,
            )
        raise RuntimeError(f"all providers failed for {model}: {last}")

"""neatlogs tracing: one WORKFLOW root per CVE run, a child span per stage.

Verified against SDK 1.4.26 on 2026-10-11 (see docs/spikes.md):
* only a WORKFLOW root finalizes; AGENT/CHAIN roots stay pending or dead-letter;
* ``identify()`` has no ``parent_session_id``: the campaign link is a tag plus
  the ``heirloom.campaign_id`` attribute;
* the gateway reports zero cost, so ``heirloom.cost_usd`` is set explicitly.

Every stage span carries all §5 attributes with explicit values (no empty
strings), and the five detection predicates are evaluated locally so the
before/after numbers never depend on ingestion timing.
"""

from __future__ import annotations

import os
from collections.abc import Callable, Iterator, Mapping
from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import Any

Attr = str | bool | int | float

ATTR_DEFAULTS: dict[str, Attr] = {
    "cve": "NONE",
    "line": "NONE",
    "stage": "NONE",
    "verdict": "PENDING",
    "calibrated": False,
    "reach": False,
    "reason": "NONE",
    "tests_edited_after_red": False,
    "claims_unlinked": 0,
    "cost_usd": 0.0,
    "claim_id": "NONE",
    "campaign_id": "NONE",
}

# Child span kinds. GUARDRAIL children are verified under a WORKFLOW root.
STAGE_KINDS: dict[str, str] = {
    "locate": "TOOL",
    "c0": "GUARDRAIL",
    "probe": "AGENT",
    "calibrate": "GUARDRAIL",
    "presence": "GUARDRAIL",
    "adapt": "AGENT",
    "verify": "GUARDRAIL",
    "behaviour": "GUARDRAIL",
    "decide": "TOOL",
}


def _detections() -> dict[str, Callable[[Mapping[str, Attr]], bool]]:
    return {
        "not_affected_without_calibration": lambda a: (
            a["verdict"] == "NOT_AFFECTED_PROVEN" and a["calibrated"] is False
        ),
        "fix_applied_where_probe_passed": lambda a: (
            a["stage"] in ("adapt", "publish.commit") and a["verdict"] != "AFFECTED"
        ),
        "probe_never_reached_region": lambda a: (
            a["reach"] is False and a["verdict"] in ("AFFECTED", "NOT_AFFECTED_PROVEN")
        ),
        "claim_without_span": lambda a: int(a["claims_unlinked"]) > 0,
        "test_edited_after_red": lambda a: a["tests_edited_after_red"] is True,
    }


DETECTIONS = _detections()


def evaluate(attrs: Mapping[str, Attr]) -> list[str]:
    """Names of the detections whose predicate matches these span attributes."""
    full = {**ATTR_DEFAULTS, **attrs}
    return [name for name, pred in DETECTIONS.items() if pred(full)]


@dataclass
class StageSpan:
    stage: str
    attrs: dict[str, Attr]
    trace_id: str = "NONE"
    span_id: str = "NONE"
    _span: Any = None
    extra: dict[str, Attr] = field(default_factory=dict)

    def set(self, key: str, value: Attr) -> None:
        if key in ATTR_DEFAULTS:
            self.attrs[key] = value
        else:
            self.extra[key] = value

    def flush_attrs(self) -> dict[str, Attr]:
        full = {**ATTR_DEFAULTS, **self.attrs}
        if self._span is not None:
            for k, v in full.items():
                self._span.set_attribute(f"heirloom.{k}", v)
            for k, v in self.extra.items():
                self._span.set_attribute(f"heirloom.{k}", v)
        return full


def _ids(span: Any) -> tuple[str, str]:
    try:
        ctx = span.get_span_context()
        return format(ctx.trace_id, "032x"), format(ctx.span_id, "016x")
    except Exception:
        return "NONE", "NONE"


class Telemetry:
    """Wraps the SDK; a no-op (but still evaluating detections) without an API key."""

    def __init__(self) -> None:
        self.enabled = False
        self._nl: Any = None
        self.root_trace_id = "NONE"
        self.root_span_id = "NONE"

    def init(self, api_key: str, tags: list[str]) -> None:
        if not api_key or os.environ.get("HEIRLOOM_NO_TELEMETRY"):
            return
        import neatlogs

        neatlogs.init(
            api_key=api_key, workflow_name="heirloom", instrumentations=["litellm"], tags=tags
        )
        self._nl = neatlogs
        self.enabled = True

    @contextmanager
    def cve_root(self, cve: str, line: str, run_id: str, campaign_id: str) -> Iterator[None]:
        if not self.enabled:
            yield
            return
        nl = self._nl
        with (
            nl.identify(session_id=f"cve-{cve}-{line}-{run_id}"),
            nl.trace(f"cve-{cve}-{line}", kind="WORKFLOW") as root,
        ):
            for k, v in {
                **ATTR_DEFAULTS,
                "cve": cve,
                "line": line,
                "stage": "root",
                "campaign_id": campaign_id,
            }.items():
                root.set_attribute(f"heirloom.{k}", v)
            root.set_attribute("heirloom.run_id", run_id)
            self.root_trace_id, self.root_span_id = _ids(root)
            yield

    @contextmanager
    def stage(self, stage: str, base: Mapping[str, Attr]) -> Iterator[StageSpan]:
        handle = StageSpan(stage, {**base, "stage": stage})
        if not self.enabled:
            yield handle
            return
        kind = STAGE_KINDS.get(stage.split(".")[0], "TOOL")
        with self._nl.trace(stage, kind=kind) as span:
            handle._span = span
            handle.trace_id, handle.span_id = _ids(span)
            try:
                yield handle
            finally:
                handle.flush_attrs()

    def flush(self) -> None:
        if self.enabled:
            self._nl.flush()

    def shutdown(self) -> None:
        if self.enabled:
            self._nl.flush()
            self._nl.shutdown()
            self.enabled = False


def trace_url(template: str, trace_id: str, span_id: str) -> str | None:
    if trace_id in ("", "NONE") or not template:
        return None
    return template.format(trace_id=trace_id, span_id=span_id)

from heirloom.integrations.neatlogs import ATTR_DEFAULTS, DETECTIONS, evaluate


def test_clean_affected_span_matches_nothing() -> None:
    assert (
        evaluate(
            {"stage": "presence", "verdict": "AFFECTED", "calibrated": True, "reach": True}
        )
        == []
    )


def test_each_detection_fires_on_its_predicate() -> None:
    assert evaluate({"verdict": "NOT_AFFECTED_PROVEN", "calibrated": False, "reach": True}) == [
        "not_affected_without_calibration"
    ]
    assert evaluate({"stage": "adapt", "verdict": "UNPROVEN"}) == [
        "fix_applied_where_probe_passed"
    ]
    assert evaluate({"verdict": "AFFECTED", "calibrated": True, "reach": False}) == [
        "probe_never_reached_region"
    ]
    assert evaluate({"claims_unlinked": 2}) == ["claim_without_span"]
    assert evaluate({"tests_edited_after_red": True}) == ["test_edited_after_red"]


def test_defaults_are_explicit_and_non_empty() -> None:
    assert set(DETECTIONS) == {
        "not_affected_without_calibration",
        "fix_applied_where_probe_passed",
        "probe_never_reached_region",
        "claim_without_span",
        "test_edited_after_red",
    }
    assert all(v != "" for v in ATTR_DEFAULTS.values())
    assert {
        "cve",
        "line",
        "stage",
        "verdict",
        "calibrated",
        "reach",
        "reason",
        "tests_edited_after_red",
        "claims_unlinked",
        "cost_usd",
        "claim_id",
    } <= set(ATTR_DEFAULTS)

