"""VERIFY (deterministic): fail-before/pass-after, no new failures or skips, tests untouched."""

from __future__ import annotations

import hashlib
from pathlib import Path
from typing import Any

from heirloom.git_ops import git
from heirloom.integrations.neatlogs import StageSpan
from heirloom.pipeline.adapt import django_patch, lfix, tests_state
from heirloom.pipeline.context import Ctx
from heirloom.verify.runner import RunResult


def labels_for(ctx: Ctx, loc: dict[str, Any]) -> list[str]:
    labels = {t.split(".")[0] for t in loc["upstream_test_ids"]}
    for path in loc["fix_files"]:
        for prefix, extra in ctx.spec.test_labels.items():
            if path.startswith(prefix):
                labels.update(extra)
    return sorted(labels)


def outcomes(r: RunResult) -> dict[str, str]:
    data = {t: o.outcome for t, o in r.tests.items()}
    for h in r.harness_errors:
        data[f"harness: {h.split(':', 2)[1].strip() if ':' in h else h}"] = "ERROR"
    return data


def baseline(ctx: Ctx, loc: dict[str, Any], labels: list[str]) -> dict[str, Any]:
    """Per-test outcomes of the touched labels on unmodified L (cached in the ledger)."""

    def body(span: StageSpan) -> dict[str, Any]:
        tree = ctx.tree("L", loc["tip"])
        r = ctx.runner().run(tree, labels, log_path=ctx.log("verify", "baseline-L.log"))
        span.set("baseline_outcome", r.outcome)
        return {"labels": labels, "outcome": r.outcome, "summary": r.summary, "tests": outcomes(r)}

    return ctx.stage("verify.baseline", {"tip": loc["tip"], "labels": labels}, body)


def current_tree(ctx: Ctx, loc: dict[str, Any], probe: dict[str, Any], patch: str) -> Path:
    """Lfix as ADAPT left it; rebuilt from the ledger if a crash left it elsewhere."""
    path = ctx.tree_path("Lfix")
    if path.exists():
        head = git(path, "rev-parse", "HEAD").strip()
        if head == loc["base"] and django_patch(path) == patch:
            ctx.install_probe(path, probe["files"])
            return path
    return lfix(ctx, loc["base"], probe["files"], patch)


def run(
    ctx: Ctx,
    loc: dict[str, Any],
    probe: dict[str, Any],
    cal: dict[str, Any],
    adapt: dict[str, Any],
) -> dict[str, Any]:
    def body(span: StageSpan) -> dict[str, Any]:
        labels = labels_for(ctx, loc)
        base = baseline(ctx, loc, labels)
        tree = current_tree(ctx, loc, probe, adapt["patch"])
        runner = ctx.runner()
        tag = adapt["patch_sha"][:8]
        after_probe = [
            runner.run(tree, [ctx.app], log_path=ctx.log("verify", tag, f"probe-{i}.log"))
            for i in range(3)
        ]
        after = runner.run(tree, labels, log_path=ctx.log("verify", tag, "labels.log"))
        before_fail = all(r["outcome"] == "FAIL" for r in cal["lt"])
        after_pass = all(r.outcome == "PASS" for r in after_probe)
        bad = {"FAIL", "ERROR", "TIMEOUT"}
        base_tests: dict[str, str] = base["tests"]
        now = outcomes(after)
        new_failures = sorted(t for t, o in now.items() if o in bad and base_tests.get(t) not in bad)
        new_skips = sorted(t for t, o in now.items() if o == "SKIP" and base_tests.get(t) != "SKIP")
        missing = sorted(t for t in base_tests if t not in now and not t.startswith("harness"))
        edited = adapt["tests_changed"] or tests_state(tree) != adapt["tests_after"]
        if edited:
            ctx.tests_edited_after_red = True
        ok = before_fail and after_pass and not new_failures and not new_skips and not edited
        problems = []
        if not before_fail:
            problems.append("probe did not FAIL before the change")
        if not after_pass:
            outs = ", ".join(r.outcome for r in after_probe)
            details = {t: o.detail for r in after_probe for t, o in r.tests.items() if o.detail}
            problems.append(f"probe after the change: {outs}; {details}")
        if new_failures:
            problems.append(f"new failures vs baseline: {new_failures[:20]}")
        if new_skips:
            problems.append(f"new skips vs baseline: {new_skips[:20]}")
        if edited:
            problems.append("files under tests/ were edited after the red run")
        span.set("verify_ok", ok)
        span.set("tests_edited_after_red", edited)
        return {
            "ok": ok,
            "labels": labels,
            "probe_before": [r["outcome"] for r in cal["lt"]],
            "probe_after": [r.outcome for r in after_probe],
            "labels_summary": after.summary,
            "baseline_summary": base["summary"],
            "tests_compared": len(now),
            "new_failures": new_failures,
            "new_skips": new_skips,
            "missing_tests": missing,
            "tests_edited_after_red": edited,
            "hint": "\n".join(problems) if problems else None,
            "patch_sha": adapt["patch_sha"],
            "tree_digest": hashlib.sha256(adapt["patch"].encode()).hexdigest()[:16],
        }

    return ctx.stage("verify", {"patch": adapt["patch_sha"], "probe": probe["sha"]}, body)

"""Precedent store: human answers become rules, so no question is asked twice."""

from __future__ import annotations

import json
import time
from dataclasses import asdict, dataclass
from pathlib import Path


@dataclass(frozen=True)
class Precedent:
    id: str
    kind: str  # reason code or behaviour-diff kind
    scope: str  # e.g. "django/4.2"
    answer: str
    issue_url: str
    trace_id: str
    created_at: float


class PolicyStore:
    def __init__(self, path: Path) -> None:
        self.path = path

    def all(self) -> list[Precedent]:
        if not self.path.exists():
            return []
        return [Precedent(**p) for p in json.loads(self.path.read_text())]

    def match(self, kind: str, scope: str) -> Precedent | None:
        return next((p for p in self.all() if p.kind == kind and p.scope == scope), None)

    def record(self, kind: str, scope: str, answer: str, issue_url: str, trace_id: str) -> Precedent:
        existing = self.match(kind, scope)
        if existing:
            return existing
        items = self.all()
        p = Precedent(f"P{len(items) + 1:03d}", kind, scope, answer, issue_url, trace_id, time.time())
        self.path.parent.mkdir(parents=True, exist_ok=True)
        self.path.write_text(json.dumps([asdict(x) for x in [*items, p]], indent=2) + "\n")
        return p

"""DECIDE: apply a stored precedent, or ask one question (a GitHub issue) and wait."""

from __future__ import annotations

from typing import Any

from heirloom.integrations import github
from heirloom.integrations.neatlogs import StageSpan
from heirloom.pipeline.context import Ctx
from heirloom.policy import PolicyStore

OPTIONS = {
    "ADAPT_FAILED": ("publish-evidence", "retry-with-hint", "skip"),
    "BEHAVIOUR_DIFF": ("accept-difference", "match-upstream", "publish-evidence"),
}
DEFAULT_OPTIONS = ("publish-evidence", "skip")


def classify(pres: dict[str, Any], ver: dict[str, Any] | None, beh: dict[str, Any] | None) -> str:
    """The question kind, or '' when no human choice is needed."""
    if pres["verdict"] == "AFFECTED":
        if ver is None or not ver["ok"]:
            return "ADAPT_FAILED"
        if beh is None or not beh["same"]:
            return (beh or {}).get("kind") or "BEHAVIOUR_DIFF"
        return ""
    if pres["verdict"] == "NOT_AFFECTED_PROVEN":
        return ""
    return str(pres["reason"])


def run(
    ctx: Ctx,
    pres: dict[str, Any],
    ver: dict[str, Any] | None,
    beh: dict[str, Any] | None,
) -> dict[str, Any]:
    kind = classify(pres, ver, beh)
    scope = f"django/{ctx.line}"

    def body(span: StageSpan) -> dict[str, Any]:
        span.set("question_kind", kind or "NONE")
        if not kind:
            decision = "publish-fix" if pres["verdict"] == "AFFECTED" else "publish-evidence"
            return {"decision": decision, "kind": "", "asked": False, "precedent": None}
        precedent = PolicyStore(ctx.s.root / "policy" / "precedents.json").match(kind, scope)
        if precedent:
            span.set("precedent_id", precedent.id)
            return {
                "decision": precedent.answer,
                "kind": kind,
                "asked": False,
                "precedent": {"id": precedent.id, "issue": precedent.issue_url},
            }
        return {"decision": "waiting_human", "kind": kind, "asked": True, "precedent": None}

    out = ctx.stage("decide", {"kind": kind, "verdict": pres["verdict"]}, body)
    if out["decision"] == "waiting_human":
        out = {**out, "issue": ask(ctx, kind, scope, pres)}
    return out


def ask(ctx: Ctx, kind: str, scope: str, pres: dict[str, Any]) -> str:
    """Open exactly one question issue on the heirloom repo (found again by its marker)."""
    marker = f"heirloom-question:{kind}:{scope}"

    def reconcile() -> dict[str, Any] | None:
        found = github.find_issue(ctx.s.heirloom_repo, marker)
        return {"url": found["url"]} if found else None

    def body(span: StageSpan) -> dict[str, Any]:
        existing = reconcile()
        if existing:
            return existing
        options = OPTIONS.get(kind, DEFAULT_OPTIONS)
        text = "\n".join(
            [
                f"Heirloom needs a decision for **{ctx.cve}** on Django {ctx.line}: `{kind}`.",
                "",
                f"Verdict: {pres['verdict']} ({pres['reason']}): {pres['detail']}",
                "",
                "Options (answer with a comment `/heirloom answer <option>`):",
                *[f"- `{o}`" + (" (default)" if i == 0 else "") for i, o in enumerate(options)],
                "",
                "The answer is stored as a precedent and applied to future cases of this kind.",
                "",
                f"<!-- {marker} -->",
            ]
        )
        body_file = ctx.log("decide", "question.md")
        body_file.write_text(text)
        url = github.create_issue(
            ctx.s.heirloom_repo, f"[heirloom] {kind} on Django {ctx.line} ({ctx.cve})", body_file
        )
        return {"url": url}

    out = ctx.stage("decide.question", {"marker": marker}, body, effect=True, reconcile=reconcile)
    return str(out["url"])

"""The PR claims table: every claim links to its span and to a run artifact, or is struck."""

from __future__ import annotations

from collections.abc import Sequence
from dataclasses import dataclass

from heirloom.integrations.neatlogs import trace_url


@dataclass(frozen=True)
class SpanLink:
    trace_id: str
    span_id: str


@dataclass(frozen=True)
class Link:
    label: str
    url: str


@dataclass(frozen=True)
class Claim:
    id: str
    text: str
    span: SpanLink | None
    evidence: tuple[Link, ...]

    @property
    def has_span(self) -> bool:
        return self.span is not None and self.span.trace_id not in ("", "NONE")

    @property
    def has_evidence(self) -> bool:
        return bool(self.evidence) and all(e.url for e in self.evidence)

    @property
    def linked(self) -> bool:
        return self.has_span and self.has_evidence


def _cell(text: str) -> str:
    return text.replace("|", "\\|").replace("\n", " ")


def render(claims: Sequence[Claim], template: str) -> tuple[str, int]:
    """Markdown table and the number of struck (unlinked) claims."""
    rows = ["| # | Claim | Span | Evidence |", "|---|---|---|---|"]
    unlinked = 0
    for c in claims:
        if c.has_span and c.span is not None:
            url = trace_url(template, c.span.trace_id, c.span.span_id)
            label = f"`{c.span.span_id[:8]}` (trace `{c.span.trace_id[:12]}`)"
            span_cell = f"[{label}]({url})" if url else label
        else:
            span_cell = "none"
        evidence = " · ".join(f"[{_cell(e.label)}]({e.url})" for e in c.evidence if e.url) or "none"
        text = _cell(c.text)
        if not c.linked:
            unlinked += 1
            missing = " and ".join(
                m for m, ok in (("span", c.has_span), ("artifact", c.has_evidence)) if not ok
            )
            text = f"~~{text}~~ (no {missing})"
        rows.append(f"| {c.id} | {text} | {span_cell} | {evidence} |")
    return "\n".join(rows), unlinked

